/**
 * What the eye does with a planet's light, as numbers: how it adapts to the
 * brightness it sees, and how strongly it sees the sun's beams. The view
 * (planetView.ts) reads the world's hints with these; the GPU passes
 * (eyeChunk.ts) do the same arithmetic per pixel, with these constants.
 *
 * Adapting: the view's brightness is measured as the mean of the logarithm of
 * each pixel's brightness, the middle of the view counting most. The eye's own
 * level eases toward it, in the logarithm, faster when the view grows brighter
 * (pupils close quickly) than when it grows darker. The exposure is the ratio
 * of daylight's level to the eye's, softened, and held between two limits, so
 * shade and caves brighten but night stays dark.
 *
 * Pure: no Babylon, no DOM.
 */

/** The eye's constants. */
export const EYE = {
  /** The view's level, as the mean brightness of its pixels' logarithm, at which the exposure is 1: open ground by day. */
  key: 0.3,
  /** How much of the gap to daylight the exposure closes, as a power: 1 all of it, 0 none. */
  response: 0.6,
  /** Seconds the eye takes to close about two thirds of the gap when the view grows brighter, and when it grows darker. */
  tauBrighten: 0.3,
  tauDarken: 0.7,
  /** The exposure's limits by default: glare is only so far dimmed, dark only so far brightened. */
  min: 0.75,
  max: 2.2,
} as const;

/** The exposure: adapting as the eye does, at a speed and between limits, or fixed. */
export type Exposure = { mode: 'auto'; speed: number; min: number; max: number } | { mode: 'fixed'; value: number };

type HintReader = (name: string) => string | null | undefined;

const EXPOSURE_RANGE: [number, number] = [0.1, 8];
const SPEED_RANGE: [number, number] = [0.1, 10];
const clamp = (x: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, x));
/** A positive number the hint gives, held in range; undefined for `auto`, nothing, or nonsense. */
const positive = (hint: HintReader, name: string, range: [number, number]): number | undefined => {
  const v = hint(name);
  if (v === undefined || v === null || v === 'auto') return undefined;
  const n = Number(v);
  return Number.isFinite(n) && n > 0 ? clamp(n, range[0], range[1]) : undefined;
};

/**
 * The exposure the world asks for: `planet.exposure` (`auto` to adapt, or a
 * number to fix it), `planet.adaptation-speed` (a multiple of the eye's own),
 * and `planet.exposure-min` and `planet.exposure-max`. Null where the
 * visitor's tier does not adapt: the view is drawn as it is.
 */
export function exposureOf(hint: HintReader, allowed: boolean): Exposure | null {
  if (!allowed) return null;
  const fixed = positive(hint, 'planet.exposure', EXPOSURE_RANGE);
  if (fixed !== undefined) return { mode: 'fixed', value: fixed };
  const speed = positive(hint, 'planet.adaptation-speed', SPEED_RANGE) ?? 1;
  const a = positive(hint, 'planet.exposure-min', EXPOSURE_RANGE) ?? EYE.min;
  const b = positive(hint, 'planet.exposure-max', EXPOSURE_RANGE) ?? EYE.max;
  return { mode: 'auto', speed, min: Math.min(a, b), max: Math.max(a, b) };
}

/** The eye's level after `dtS` seconds of looking at a view whose level is `measured`, eased in the logarithm. */
export function adaptStep(adapted: number, measured: number, dtS: number, speed: number): number {
  if (dtS <= 0) return adapted;
  const tau = measured > adapted ? EYE.tauBrighten : EYE.tauDarken;
  const keep = Math.exp((-dtS * speed) / tau);
  if (keep < 1e-9) return measured;
  return Math.exp(Math.log(measured) + (Math.log(adapted) - Math.log(measured)) * keep);
}

/** The exposure for the eye's level: daylight's level over it, softened by the response, between the limits. */
export function exposureFor(adapted: number, limits: { min: number; max: number }): number {
  return clamp(Math.pow(EYE.key / Math.max(adapted, 1e-6), EYE.response), limits.min, limits.max);
}

/**
 * A colour channel, 0 to 1, under an exposure: about the exposure times it
 * when dark, rolling off to white, so nothing brightened clips. The view's
 * sky is drawn as 1 - e^-light, and this scales the light under it.
 */
export function exposed(x: number, e: number): number {
  return 1 - Math.pow(1 - clamp(x, 0, 1), e);
}

/** How strongly the world asks the sun's beams to show (`planet.sunbeams`, 0 to 1, `auto` for 1, `none`), where the tier draws them. */
export function sunbeamsOf(hint: HintReader, allowed: boolean): number {
  if (!allowed) return 0;
  const v = hint('planet.sunbeams');
  if (v === 'none') return 0;
  if (v === undefined || v === null || v === 'auto') return 1;
  const n = Number(v);
  return Number.isFinite(n) ? clamp(n, 0, 1) : 1;
}

const smoothstep = (a: number, b: number, x: number) => {
  const t = clamp((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
};

/** How strongly the sun's beams show for the sun's height, as the sine of its elevation: none below the horizon, strongest low in the sky. */
export function sunbeamsByHeight(sinElevation: number): number {
  return smoothstep(-0.01, 0.05, sinElevation) * (1 - 0.6 * smoothstep(0.2, 0.8, sinElevation));
}

/** How strongly the sun's beams show for where the sun is on the screen, in normalised device coordinates: whole within the view, gone well outside it or behind the eye. */
export function sunOnScreen(x: number, y: number, inFront: boolean): number {
  if (!inFront) return 0;
  return 1 - smoothstep(1, 1.6, Math.max(Math.abs(x), Math.abs(y)));
}
